import requests
for repo in ['pydeseq2','gseapy','python']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20'
    try:
        r=requests.get(url,timeout=20)
        print('\\n', repo, r.status_code)
        if r.ok:
            data=r.json()
            for t in data.get('tags',[])[:10]:
                print(t.get('name'))
        else:
            print(r.text[:200])
    except Exception as e:
        print(repo, type(e).__name__, e)
